    private MultiverseCharacterOptionEngine(){}
    private static void add(String n,String b,String t,int p,double s){ALL.put(norm(n),new Def(n,b,t,p,s));}

    public static JSONArray allSpecies(){JSONArray a=new JSONArray();for(Def d:ALL.values())a.put(d.name);return a;}
    public static boolean isKnownSpecies(String s){return ALL.containsKey(norm(s));}
    public static JSONObject lookupSpecies(String s){JSONObject o=new JSONObject();try{Def d=ALL.get(norm(s));if(d==null)return o.put("known",false);return o.put("known",true).put("species",d.name).put("base_species",d.base).put("source",SOURCE).put("page",d.page).put("runtime","MultiverseCharacterOptionEngine").put("mechanics_compiled",true);}catch(Exception e){return o;}}

    /** Multiverse usa ASI flexível. Esta função nunca escolhe atributos pelo usuário. */
    public static boolean apply2014AbilityBonuses(JSONObject o){if(o==null||!isKnownSpecies(o.optString("species")))return false;try{pending(o,"ASI Multiverse: escolha +2 em um atributo e +1 em outro, ou +1 em três atributos diferentes");o.put("origin_ability_bonus","ASI flexível de Multiverse pendente de escolha");o.put("multiverse_asi_pending",true);return true;}catch(Exception e){return false;}}

    public static String speedOverride(String species){Def d=ALL.get(norm(species));if(d==null)return "";return meters(d.speed);}

