    public static JSONObject longRest(JSONObject o){if(o==null)return new JSONObject();try{if(!isKnownSpecies(o.optString("species")))return o;String b=norm(baseName(o));resetUses(o,"eladrin_fey_step_uses",pb(o));resetUses(o,"firbolg_hidden_step_uses",pb(o));resetUses(o,"svirfneblin_camouflage_uses",pb(o));resetUses(o,"fury_of_small_uses",pb(o));resetUses(o,"stone_endurance_uses",pb(o));resetUses(o,"fey_gift_uses",pb(o));resetUses(o,"fortune_many_uses",pb(o));resetUses(o,"kenku_recall_advantage_uses",pb(o));resetUses(o,"draconic_cry_uses",pb(o));resetUses(o,"rabbit_hop_uses",pb(o));resetUses(o,"shifting_uses",pb(o));resetUses(o,"adrenaline_rush_uses",pb(o));resetUses(o,"hungry_jaws_uses",pb(o));resetUses(o,"raven_queen_blessing_uses",pb(o));resetUses(o,"relentless_endurance_uses",1);if(b.equals("aasimar")){resetUses(o,"aasimar_healing_hands_uses",1);o.put("aasimar_revelation_spent",false);}JSONObject spells=o.optJSONObject("species_spell_uses_remaining");JSONObject max=o.optJSONObject("species_spell_uses_max");if(spells!=null&&max!=null){Iterator<String> it=max.keys();while(it.hasNext()){String k=it.next();spells.put(k,max.optInt(k));}o.put("species_spell_uses_remaining",spells);}o.put("multiverse_long_rest_reset",true);}catch(Exception ignored){}return o;}

    public static JSONObject castSpeciesSpell(JSONObject o,String spell){JSONObject r=new JSONObject();try{if(o==null||!isKnownSpecies(o.optString("species")))return r.put("ok",false).put("reason","species_not_multiverse");String k=norm(spell);JSONObject levels=o.optJSONObject("species_spell_min_level");if(levels==null||!levels.has(k))return r.put("ok",false).put("reason","spell_not_granted");int min=levels.optInt(k,1);if(o.optInt("level",1)<min)return r.put("ok",false).put("reason","level_too_low").put("minimum_level",min);JSONObject max=o.optJSONObject("species_spell_uses_max");if(max==null||max.optInt(k,-1)<0)return r.put("ok",true).put("spell",spell).put("free_cast",true).put("unlimited",true);JSONObject cur=o.optJSONObject("species_spell_uses_remaining");int n=cur==null?0:cur.optInt(k,0);if(n<=0)return r.put("ok",false).put("reason","no_free_uses_remaining");cur.put(k,n-1);o.put("species_spell_uses_remaining",cur);return r.put("ok",true).put("spell",spell).put("free_cast",true).put("remaining",n-1).put("state_mutated",true);}catch(Exception e){return r;}}

    private static void addSpell(JSONObject o,String spell,int min,String recharge,boolean abilityChoice)throws Exception{JSONArray a=o.optJSONArray("species_spells");if(a==null)a=new JSONArray();boolean found=false;for(int i=0;i<a.length();i++)if(norm(a.optString(i)).equals(norm(spell)))found=true;if(!found)a.put(spell);o.put("species_spells",a);String k=norm(spell);JSONObject lv=o.optJSONObject("species_spell_min_level");if(lv==null)lv=new JSONObject();lv.put(k,min);o.put("species_spell_min_level",lv);JSONObject mx=o.optJSONObject("species_spell_uses_max");if(mx==null)mx=new JSONObject();JSONObject cur=o.optJSONObject("species_spell_uses_remaining");if(cur==null)cur=new JSONObject();int uses="at_will".equals(recharge)?-1:("pb_long_rest".equals(recharge)?pb(o):1);mx.put(k,uses);if(!cur.has(k))cur.put(k,uses);o.put("species_spell_uses_max",mx).put("species_spell_uses_remaining",cur);if(abilityChoice)pending(o,"Atributo de conjuração da espécie para "+spell+": escolha Inteligência, Sabedoria ou Carisma");}
    private static boolean consume(JSONObject o,String key)throws Exception{int n=o.optInt(key,0);if(n<=0)return false;o.put(key,n-1);return true;}
    private static void setUses(JSONObject o,String key,int n)throws Exception{if(!o.has(key))o.put(key,Math.max(0,n));o.put(key+"_max",Math.max(0,n));}
    private static void resetUses(JSONObject o,String key,int n)throws Exception{if(o.has(key)||o.has(key+"_max")){o.put(key,Math.max(0,n)).put(key+"_max",Math.max(0,n));}}
    private static JSONObject wrong(JSONObject r)throws Exception{return r.put("ok",false).put("reason","wrong_species");}
    private static JSONObject empty(JSONObject r)throws Exception{return r.put("ok",false).put("reason","no_uses_remaining");}
    private static JSONObject need(JSONObject r,String key)throws Exception{return r.put("ok",false).put("reason","explicit_input_required").put("required",key);}
    private static boolean base(JSONObject o,String expected){return norm(baseName(o)).equals(norm(expected));}
    private static String baseName(JSONObject o){Def d=ALL.get(norm(o.optString("species")));return d==null?"":d.base;}
    private static int pb(JSONObject o){int l=Math.max(1,Math.min(20,o.optInt("level",1)));return 2+(l-1)/4;}
    private static int mod(int score){return (int)Math.floor((score-10)/2.0);}
    private static int abilityMod(JSONObject o,String a){String n=norm(a);if(n.startsWith("int"))return mod(o.optInt("int_score",10));if(n.startsWith("sab")||n.startsWith("wis"))return mod(o.optInt("wis",10));if(n.startsWith("car")||n.startsWith("cha"))return mod(o.optInt("cha",10));return Math.max(mod(o.optInt("int_score",10)),Math.max(mod(o.optInt("wis",10)),mod(o.optInt("cha",10))));}
    private static int clamp(int v,int a,int b){return Math.max(a,Math.min(b,v));}
    private static double dSpeed(JSONObject o){Def d=ALL.get(norm(o.optString("species")));return d==null?9:d.speed;}
    private static String meters(double x){return Math.abs(x-Math.rint(x))<0.001?((int)Math.rint(x))+" m":String.format(Locale.ROOT,"%.1f m",x).replace('.',',');}
    private static void size(JSONObject o,String s)throws Exception{o.put("size_options",s);}
    private static void sizeChoice(JSONObject o)throws Exception{o.put("size_options","Pequeno|Médio");pending(o,"Tamanho Multiverse: escolha Pequeno ou Médio");}
    private static void darkvision(JSONObject o,int m)throws Exception{o.put("darkvision_m",m);String p=o.optString("passive_senses","");if(!norm(p).contains("visao no escuro"))o.put("passive_senses",p+(p.trim().isEmpty()?"":" • ")+"Visão no Escuro "+m+" m");}
    private static void powerful(JSONObject o)throws Exception{o.put("powerful_build",true).put("carrying_capacity_multiplier",2).put("carrying_capacity",Math.max(1,o.optInt("str",10)*14)+" kg (aprox.; Porte Poderoso)");}
    private static void naturalAttack(JSONObject o,String name,String damage)throws Exception{feature(o,name+": golpe desarmado "+damage);token(o,"natural_attacks",name+"="+damage);}
    private static void feature(JSONObject o,String f)throws Exception{String x=o.optString("features","");if(!norm(x).contains(norm(f)))o.put("features",x+(x.trim().isEmpty()?"":"\n")+"Traço de espécie: "+f+".");}
    private static void pending(JSONObject o,String choice)throws Exception{JSONArray a=o.optJSONArray("species_choice_pending");if(a==null)a=new JSONArray();for(int i=0;i<a.length();i++)if(norm(a.optString(i)).equals(norm(choice)))return;a.put(choice);o.put("species_choice_pending",a).put("species_choices_complete",false);}
    private static void token(JSONObject o,String key,String v)throws Exception{String raw=o.optString(key,"");String nv=norm(v);for(String p:raw.split("[|,;•]"))if(norm(p).equals(nv))return;o.put(key,raw.trim().isEmpty()?v:raw+"|"+v);}
    private static void grantSkill(JSONObject o,String skill)throws Exception{String raw=o.optString("skills","");if(!norm(raw).contains(norm(skill)))o.put("skills",raw+(raw.trim().isEmpty()?"":" • ")+skill+" "+signed(skillMod(o,skill)+pb(o))+" ★");token(o,"species_skill_proficiencies",skill);}
    private static int skillMod(JSONObject o,String skill){String n=norm(skill);int s;if(n.equals("atletismo"))s=o.optInt("str",10);else if(n.equals("acrobacia")||n.equals("furtividade")||n.equals("prestidigitacao"))s=o.optInt("dex",10);else if(n.equals("arcanismo")||n.equals("historia")||n.equals("investigacao")||n.equals("natureza")||n.equals("religiao"))s=o.optInt("int_score",10);else if(n.equals("lidar com animais")||n.equals("adestrar animais")||n.equals("intuicao")||n.equals("medicina")||n.equals("percepcao")||n.equals("sobrevivencia"))s=o.optInt("wis",10);else s=o.optInt("cha",10);return mod(s);}
    private static String signed(int n){return n>=0?"+"+n:String.valueOf(n);}
    private static String norm(String s){String x=Normalizer.normalize(s==null?"":s.toLowerCase(Locale.ROOT),Normalizer.Form.NFD).replaceAll("\\p{M}+","");return x.replaceAll("[^a-z0-9]+"," ").trim();}
